INSERT INTO uploader_variants VALUES (160, '5643502a403a4ac20e3fadea', '2023-01-16T10:07:48.598Z', '2020-07-15T15:20:13.897Z', '99-Adhoc Patching Requests', 'CVE-2020-1350', 'On July 14, 2020 Microsoft released a security update to address a remote code execution vulnerability affecting Windows Domain Name System (DNS) Servers. Windows Servers with operating systems that are no longer under vendor support (Windows Server 2003, Server 2008, Server 2008 R2) cannot be patched and full mitigation is via a registry-based workaround only. The workaround requires a restart of the DNS service and does not require a reboot. Impact to service is negligible and only briefly affects DNS requests while the service is stopped and restarted. CenturyLink will be proactively applying the registry workaround on managed servers with Server 2003, Server 2008 and Server 2008 R2 from July 29.
